class pombo(Animal): def idade(self): print (“define a idade pombo”) def cor(self): print (“define a cor pombo”) def mamifero(self): print (“pombo não é mamifero”)
class coelho(Animal): def idade(self): print (“define a idade do coelho”) def cor(self): print (“define a cor do coelho”)
class cavalo(Animal): def idade(self): print (“define a idade do cavalo”) def cor(self): print (“define a cor do cavalo”)
obj1 = coelho() obj2 = pombo() obj3 = cavalo() for type in (obj1, obj2, obj3):
type.idade() type.cor() type.mamifero()
